package org.traccar.protocol;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.net.SocketAddress;

public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexDefaultTest() {
        Protocol protocol = new Protocol();
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Assert.assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerDefaultTest() {
        Protocol protocol = new Protocol();
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Assert.assertEquals("Unknown", decoder.getManufacturer());
    }

    @Test
    public void decodeNullChannelAndAddressTest() {
        Protocol protocol = new Protocol();
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        Object msg = "testMessage";

        Object result = null;
        try {
            result = decoder.decode(null, null, msg);
        } catch (Exception e) {
            e.printStackTrace();
        }

        Assert.assertNull(result);
    }

    @Test
    public void decodeWithMockChannelAndAddressTest() {
        Protocol protocol = new Protocol();
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        Object msg = "testMessage";

        Channel channel = Mockito.mock(Channel.class);
        SocketAddress address = Mockito.mock(SocketAddress.class);

        Object result = null;
        try {
            result = decoder.decode(channel, address, msg);
        } catch (Exception e) {
            e.printStackTrace();
        }

        Assert.assertNull(result);
    }

    @Test
    public void decodeWithMockChannelAndAddressAndNonStringDataTest() {
        Protocol protocol = new Protocol();
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        ByteBuf msg = Unpooled.buffer().writeInt(123);

        Channel channel = Mockito.mock(Channel.class);
        SocketAddress address = Mockito.mock(SocketAddress.class);

        Object result = null;
        try {
            result = decoder.decode(channel, address, msg);
        } catch (Exception e) {
            e.printStackTrace();
        }

        Assert.assertNull(result);
    }
}
